import asyncio
import copy
import json
import pathlib
import sys
import tempfile
import unittest

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parents[1]))
import client_example as bridge
import reboot_hil as reboot
from test_hil_runner import FakeClient, FakeDevice, FakeOracle


class RebootDevice(FakeDevice):
    def __init__(self):
        super().__init__()
        self.clients = []
        self.reset_count = 0
        self.raw_writes = []
        self.pending = None
        self.no_restart = False
        self.complete_before_reset = False


class RebootClient(FakeClient):
    def __init__(self, device, **kwargs):
        super().__init__(device, **kwargs)
        device.clients.append(self)
        self.tx_probe = None

    async def request(self, method, path, body=""):
        if path == "/json/fxdata" and self.tx_probe is not None:
            self.device.pending = asyncio.get_running_loop().create_future()
            self.tx_probe.observe((5000).to_bytes(2, "little") + b"first")
            return await self.device.pending
        return await super().request(method, path, body)

    async def write_gatt_char(self, uuid, data, response=True):
        self.device.raw_writes.append(bytes(data))


class RebootOracle(FakeOracle):
    async def snapshot(self, update=None):
        result = await super().snapshot(update)
        if update is not None:
            # Advance simulated running time between scenarios, avoiding wall-clock sleeps.
            self.device.info["uptime"] += 100
            result["info"]["uptime"] = self.device.info["uptime"]
        return result

    async def reboot(self):
        self.device.reset_count += 1
        for client in self.device.clients:
            client.is_connected = False
        if not self.device.no_restart:
            self.device.info["uptime"] = 1
        if self.device.pending is not None and not self.device.pending.done():
            if self.device.complete_before_reset:
                self.device.pending.set_result(bridge.BridgeResponse(200, "application/json", '["completed"]'))
            else:
                self.device.pending.set_exception(ConnectionError("WLED disconnected"))
        return 200


class RebootTests(unittest.IsolatedAsyncioTestCase):
    def setUp(self):
        self.directory = tempfile.TemporaryDirectory()
        self.addCleanup(self.directory.cleanup)
        self.args = reboot.parse_args(["--address", "test", "--http-url", "http://test",
                                       "--output", self.directory.name, "--allow-reboot-tests"])
        self.device = RebootDevice()
        self.oracle = RebootOracle(self.device)

    def runner(self, oracle=None):
        return reboot.RebootHilRunner(self.args,
                                      client_factory=lambda _address, **kwargs: RebootClient(self.device, **kwargs),
                                      oracle=oracle or self.oracle)

    async def test_all_reboot_phases_restore_state_and_record_proof(self):
        before = copy.deepcopy(self.device.state)
        runner = self.runner()
        self.assertEqual(await runner.run(), 0)
        self.assertEqual(self.device.reset_count, 3)
        self.assertEqual(self.device.state, before)
        self.assertEqual(self.device.raw_writes, [b"\x20\x00GET /json"])
        self.assertEqual(len(runner.expected_reboots), 3)
        self.assertEqual(runner.expected_reboots[-1]["response_bytes_received_at_dispatch"], 5)
        self.assertEqual(runner.expected_reboots[-1]["response_bytes_expected"], 5000)
        result = json.loads((pathlib.Path(self.directory.name) / "results.json").read_text())
        self.assertEqual(result["outcome"], "passed_selected_coverage")
        self.assertIn("Software reboot", result["coverage_limits"][0])

    async def test_identity_mismatch_prevents_reset(self):
        wrong = RebootDevice()
        wrong.info["mac"] = "112233445566"
        runner = self.runner(RebootOracle(wrong))
        self.assertEqual(await runner.run(), 1)
        self.assertEqual(self.device.reset_count, 0)
        self.assertEqual(wrong.reset_count, 0)
        self.assertEqual(self.device.posts, [])

    async def test_ble_drop_alone_does_not_excuse_uptime(self):
        self.args.reboot_timeout = 0.015
        runner = self.runner()
        await runner.setup()
        self.device.no_restart = True
        previous = runner.previous_uptime
        with self.assertRaisesRegex(AssertionError, "No verified HTTP restart"):
            await runner.idle_reset()
        self.assertEqual(runner.previous_uptime, previous)
        self.assertEqual(runner.expected_reboots, [])
        await runner.disconnect()

    async def test_missed_response_interruption_is_incomplete(self):
        runner = self.runner()
        await runner.setup()
        self.device.complete_before_reset = True
        with self.assertRaisesRegex(reboot.CoverageMissing, "both bounded attempts"):
            await runner.long_tx_reset()
        self.assertEqual(self.device.reset_count, 2)
        self.assertEqual(len(runner.expected_reboots), 2)
        await runner.restore()
        await runner.disconnect()

    async def test_recovery_failure_is_not_rewritten_as_success(self):
        runner = self.runner()
        await runner.setup()
        original_reboot = self.oracle.reboot

        async def reset_then_fail_connections():
            result = await original_reboot()
            self.device.connect_fails = True
            return result

        self.oracle.reboot = reset_then_fail_connections
        self.assertFalse(await runner.case("reboot", runner.idle_reset))
        self.assertEqual(runner.records[-1]["status"], "fail")
        self.assertEqual(len(runner.records[-1]["recovery"]), 2)
        self.assertEqual(runner.expected_reboots, [])
        self.assertEqual(runner.previous_uptime, 100)

    def test_packet_probe_tracks_byte_lengths_without_retaining_payload(self):
        probe = reboot.TxProbe()
        probe.observe(b"\x05\x00ab")
        self.assertTrue(probe.incomplete)
        self.assertTrue(probe.first_chunk.is_set())
        probe.observe(b"cde")
        self.assertFalse(probe.incomplete)
        self.assertEqual(probe.received, 5)
        self.assertNotIn("payload", vars(probe))

    def test_reboot_requires_explicit_mode_and_http_recovery(self):
        common = ["--address", "test", "--output", self.directory.name]
        with self.assertRaises(SystemExit):
            reboot.parse_args(common + ["--http-url", "http://test"])
        with self.assertRaises(SystemExit):
            reboot.parse_args(common + ["--allow-reboot-tests", "--serial-port", "unused"])


if __name__ == "__main__":
    unittest.main()
